        # If it's a coupled shift, we also need to check the leader's limit if it exists.
        leader = getattr(method, "leader_shift", None)
        if leader and method.configuration.maximum_number_of_participants is None:
            leader_method = leader.signup_method
            if (
                hasattr(leader_method, "configuration")
                and hasattr(leader_method.configuration, "maximum_number_of_participants")
                and leader_method.configuration.maximum_number_of_participants is not None
            ):
                current_count = len(
                    [
                        p
                        for p in leader.participations.all()
                        if p.state == AbstractParticipation.States.CONFIRMED
                    ]
                )
                if current_count >= leader_method.configuration.maximum_number_of_participants:
                    return SignupDisallowedError(_("The maximum number of participants is reached."))

    def get_participant_count_bounds(self):
        min_val = self.configuration.minimum_number_of_participants
        max_val = self.configuration.maximum_number_of_participants

        leader = getattr(self, "leader_shift", None)
        if leader and max_val is None:
            leader_method = leader.signup_method
            if (
                hasattr(leader_method, "configuration")
                and hasattr(leader_method.configuration, "maximum_number_of_participants")
                and leader_method.configuration.maximum_number_of_participants is not None
            ):
                max_val = leader_method.configuration.maximum_number_of_participants

        if leader and min_val is None:
             leader_method = leader.signup_method
             if (
                 hasattr(leader_method, "configuration")
                 and hasattr(leader_method.configuration, "minimum_number_of_participants")
                 and leader_method.configuration.minimum_number_of_participants is not None
             ):
                min_val = leader_method.configuration.minimum_number_of_participants

        return (
            min_val,
            max_val,
        )

    # ... (other methods)

    def get_shift_state_context_data(self, request, **kwargs):
        context_data = super().get_shift_state_context_data(request, **kwargs)
        min_val, _ = self.get_participant_count_bounds()
        context_data["empty_spots"] = range(
            max(
                0,
                (min_val or 0)
                - len(context_data["participations"]),
            )
        )
