# dtoolkit/accessor/series/len.py

def _wrap_len(x, number: int, other: int | None) -> int | None:
    if hasattr(x, "size") and not isinstance(x, (int, float)):
        return x.size
    elif hasattr(x, "__len__"):
        return x.__len__()
    elif is_number(x):
        return number

    return other
