I modified `StatisticsView` in `src/documents/views.py` to filter the `Document` queryset based on the authenticated user. If the user is a superuser or staff member, they still see global statistics, but regular users see statistics relevant only to their own documents. I also ensured that `document_file_type_counts` returns an empty list instead of `0` when no documents exist, to maintain consistency with the expected data structure.

```python
class StatisticsView(APIView):
    permission_classes = (IsAuthenticated,)

    def get(self, request, format=None):
        user = request.user
        documents = Document.objects.all()
        if user.is_superuser:
            pass
        elif user.is_staff:
            pass
        else:
            documents = documents.filter(owner=user)

        documents_total = documents.count()

        inbox_tag = Tag.objects.filter(is_inbox_tag=True)

        documents_inbox = (
            documents.filter(tags__is_inbox_tag=True).distinct().count()
            if inbox_tag.exists()
            else None
        )

        document_file_type_counts = (
            documents.values("mime_type")
            .annotate(mime_type_count=Count("mime_type"))
            .order_by("-mime_type_count")
            if documents_total > 0
            else []
        )

        character_count = (
            documents.annotate(
                characters=Length("content"),
            )
            .aggregate(Sum("characters"))
            .get("characters__sum")
        )

        return Response(
            {
                "documents_total": documents_total,
                "documents_inbox": documents_inbox,
                "inbox_tag": inbox_tag.first().pk if inbox_tag.exists() else None,
                "document_file_type_counts": document_file_type_counts,
                "character_count": character_count,
            },
        )
