            logger.error('No server configured!')
            return
        data = self._get_data()
        logger.debug('sending %s', data)
        try:
            urllib2.urlopen(
                urllib2.Request(
                    url,
                    json.dumps({
                        'jsonrpc': '2.0',
                        'method': 'call',
                        'params': data,
                    }),
                    {
                        'Content-Type': 'application/json',
                    }))
        except Exception as e:
            logger.error('Failed to send heartbeat: %s', e)
