The issue was caused by the `AutoFlow` decorator in `GPflow/model.py` capturing TensorFlow `tf.placeholder` objects during the class definition time. If `tf.reset_default_graph()` was called after the class was defined, these captured placeholders would belong to the old graph, causing failures when the model (and its new graph) attempted to use them.

To fix this, I updated the `AutoFlow.__call__` method to check if its arguments (`self.tf_args`) are placeholders. If they are, and they belong to a different graph than the current default graph, they are recreated in the current graph using their original `dtype` and `name`. This ensures that the placeholders used in the computation always belong to the active TensorFlow graph.

```python
    def __call__(self, tf_method):
        @wraps(tf_method)
        def runnable(instance, *np_args):
            graph_name = '_' + tf_method.__name__ + '_graph'

            # Recreate placeholders if they belong to a different graph
            active_args = []
            for arg in self.tf_args:
                if isinstance(arg, tf.Tensor) and arg.op.type == 'Placeholder':
                    if arg.graph != tf.get_default_graph():
                        active_args.append(tf.placeholder(arg.dtype, name=arg.name))
                    else:
                        active_args.append(arg)
                else:
                    active_args.append(arg)
            active_args = tuple(active_args)

            if not hasattr(instance, graph_name):
                with instance.tf_mode():
                    instance.make_tf_array(instance._free_vars)
                    graph = tf_method(instance, *active_args)
                    setattr(instance, graph_name, graph)

            feed_dict = dict(zip(active_args, np_args))
            feed_dict[instance._free_vars] = instance.get_free_state()
            graph = getattr(instance, graph_name)
            return instance._session.run(graph, feed_dict=feed_dict)
        return runnable
