        time.sleep(10)
        return client.run_instances(aws_retry=True, **instance_spec)
    except is_boto3_error_code('InsufficientInstanceCapacity'):
        # Use AWSRetry to retry when AWS is out of capacity for the requested instance type in the AZ.
